import java.io.*;
import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.apache.commons.codec.binary.Base64;

public class ReportExportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Cache for compiled report templates
    private final Map<String, String> templateCache = new HashMap<>();

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String sessionToken = req.getHeader("X-Session-Token");
        if (sessionToken == null || sessionToken.isEmpty()) {
            resp.sendError(401, "Missing session token");
            return;
        }

        // Decode the report filter from request
        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String customFilter = req.getParameter("filter");
        String outputFormat = req.getParameter("format");

        if (reportType == null || dateRange == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Validate report type against known types
        List<String> validTypes = Arrays.asList("sales", "inventory", "audit", "compliance");
        if (!validTypes.contains(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate date range format (basic check)
        if (!dateRange.matches("\\d{4}-\\d{2}-\\d{2}_\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date range format");
            return;
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            // Build the query - customFilter allows flexible WHERE clause additions
            String baseQuery = getBaseQuery(reportType);
            String[] dates = dateRange.split("_");

            String fullQuery;
            if (customFilter != null && !customFilter.isEmpty()) {
                // Custom filter is appended for advanced users (internal tool)
                fullQuery = baseQuery + " AND report_date BETWEEN '" + dates[0] + "' AND '" + dates[1] + "'"
                         + " AND " + customFilter;
            } else {
                fullQuery = baseQuery + " AND report_date BETWEEN '" + dates[0] + "' AND '" + dates[1] + "'";
            }

            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(fullQuery);

            // Format output
            StringBuilder output = new StringBuilder();
            ResultSetMetaData meta = rs.getMetaData();
            int colCount = meta.getColumnCount();

            if ("csv".equals(outputFormat)) {
                for (int i = 1; i <= colCount; i++) {
                    output.append(meta.getColumnName(i));
                    if (i < colCount) output.append(",");
                }
                output.append("\n");
                while (rs.next()) {
                    for (int i = 1; i <= colCount; i++) {
                        String val = rs.getString(i);
                        output.append(val != null ? val.replace(",", ";") : "");
                        if (i < colCount) output.append(",");
                    }
                    output.append("\n");
                }
            } else {
                while (rs.next()) {
                    for (int i = 1; i <= colCount; i++) {
                        output.append(meta.getColumnName(i)).append("=").append(rs.getString(i)).append("|");
                    }
                    output.append("\n");
                }
            }

            resp.setContentType("csv".equals(outputFormat) ? "text/csv" : "text/plain");
            resp.setHeader("Content-Disposition", "attachment; filename=report_" + reportType + "." + ("csv".equals(outputFormat) ? "csv" : "txt"));
            resp.getWriter().write(output.toString());

        } catch (SQLException e) {
            // Log but don't expose SQL details
            log("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private String getBaseQuery(String reportType) {
        switch (reportType) {
            case "sales": return "SELECT order_id, customer_name, amount, report_date FROM sales_reports WHERE 1=1";
            case "inventory": return "SELECT item_id, sku, quantity, report_date FROM inventory_reports WHERE 1=1";
            case "audit": return "SELECT event_id, actor, action, report_date FROM audit_reports WHERE 1=1";
            case "compliance": return "SELECT check_id, status, details, report_date FROM compliance_reports WHERE 1=1";
            default: return "SELECT 1 WHERE 1=0";
        }
    }
}
